<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { Plus, Search, Refresh, EditPen, Delete, Promotion, Download, Link } from '@element-plus/icons-vue'; import { enterpriseApi, type BatchQuery } from '@/api/enterprise'; import type { BatchDetail, BatchForm, BatchListItem } from '@/types/domain'; import PageHeader from '@/components/PageHeader.vue'; import FilterBar from '@/components/FilterBar.vue'; import PaginationBar from '@/components/PaginationBar.vue'; import StatusTag from '@/components/StatusTag.vue'; import EmptyState from '@/components/EmptyState.vue'; import { useAsyncAction } from '@/composables/useAsyncAction'
const rows = ref<BatchListItem[]>([]); const total = ref(0); const loading = ref(false); const dialogVisible = ref(false); const detailVisible = ref(false); const detail = ref<BatchDetail>(); const editingId = ref<string>(); const { loading: actionLoading, run } = useAsyncAction(); const query = reactive<BatchQuery>({ current: 1, size: 10, batchStatus: 1, batchNo: '', productVariety: '', upstreamBatchNo: '' }); const form = reactive<BatchForm>({ batchNo: '', productVariety: '', sourceType: 1, publish: false, sendConfirmRequest: false, remark: '', catchBreedDate: '', certificateNo: '', departureTemp: undefined, drugReportNo: '', fishingLogNo: '' })
const statuses = [{ value: 1, label: '新建' }, { value: 2, label: '待确认' }, { value: 3, label: '已确认' }, { value: 4, label: '已发布' }]
const statusTone = (status: number) => status === 3 || status === 4 ? 'success' : status === 2 ? 'warning' : status === 5 ? 'danger' : 'info'
async function load() { loading.value = true; try { const result = await enterpriseApi.batches(query); rows.value = result.records; total.value = result.total } catch (error) { ElMessage.error(error instanceof Error ? error.message : '批号列表加载失败') } finally { loading.value = false } }
function resetForm() { Object.assign(form, { batchNo: '', productVariety: '', sourceType: 1, publish: false, sendConfirmRequest: false, remark: '', catchBreedDate: '', certificateNo: '', departureTemp: undefined, drugReportNo: '', fishingLogNo: '' }); editingId.value = undefined }
async function openEditor(row?: BatchListItem) { resetForm(); if (row) { const data = await enterpriseApi.batchDetail(row.id); editingId.value = row.id; Object.assign(form, { ...data, ...data.fishingInfo }) } dialogVisible.value = true }
async function submit() { try { if (editingId.value) await run(() => enterpriseApi.updateBatch(editingId.value!, form), '批号已更新'); else await run(() => enterpriseApi.createBatch(form), '批号已创建'); dialogVisible.value = false; load() } catch { /* message handled by useAsyncAction */ } }
async function remove(row: BatchListItem) { await ElMessageBox.confirm(`确定删除批号「${row.batchNo}」吗？`, '删除批号', { type: 'warning' }); await run(() => enterpriseApi.deleteBatch(row.id), '批号已删除'); load() }
async function publish(row: BatchListItem) { await run(() => enterpriseApi.publishBatch(row.id), '批号已发布'); load() }
async function offShelf(row: BatchListItem) { const result = await ElMessageBox.prompt('请输入下架原因（可选）', '下架批号', { inputPlaceholder: '例如：库存售罄、冷链维护' }).catch(() => null); if (result) { await run(() => enterpriseApi.offShelfBatch(row.id, result.value), '批号已下架'); load() } }
async function showTrace(row: BatchListItem) { const data = await enterpriseApi.traceCode(row.id); if (data?.traceCode) { await navigator.clipboard?.writeText(data.traceCode); ElMessage.success(`溯源码 ${data.traceCode} 已复制`) } else ElMessage.info('该批号暂未生成溯源码') }
onMounted(load)
</script>
<template><div class="batch-list-view"><PageHeader eyebrow="COLD CHAIN OPERATIONS" title="产品批号" description="管理本企业批号、发布状态与上下游交接"><template #default><el-button type="primary" :icon="Plus" @click="openEditor()">新建批号</el-button></template></PageHeader><FilterBar><el-select v-model="query.batchStatus" placeholder="批号状态" style="width: 130px"><el-option v-for="item in statuses" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-input v-model="query.batchNo" clearable placeholder="批号" style="width: 190px" @keyup.enter="query.current = 1; load()" /><el-input v-model="query.productVariety" clearable placeholder="产品品种" style="width: 170px" @keyup.enter="query.current = 1; load()" /><template #actions><el-button type="primary" :icon="Search" @click="query.current = 1; load()">查询</el-button><el-button :icon="Refresh" @click="Object.assign(query, { batchNo: '', productVariety: '', upstreamBatchNo: '', current: 1 }); load()">重置</el-button></template></FilterBar><section class="data-panel batch-table-panel"><div class="data-panel__head"><div><strong>批号列表</strong><span>当前筛选：{{ statuses.find((item) => item.value === query.batchStatus)?.label }}</span></div><span class="table-caption">共 {{ total }} 条</span></div><el-table v-loading="loading" :data="rows" row-key="id" min-width="920"><el-table-column label="批号" min-width="190"><template #default="{ row }"><div class="batch-no-cell"><strong>{{ row.batchNo }}</strong><small>{{ row.productVariety || '品种未填写' }}</small></div></template></el-table-column><el-table-column label="上游批号" min-width="180"><template #default="{ row }"><span>{{ row.upstreamBatchNo || '-' }}</span><small v-if="row.upstreamEnterpriseName" class="cell-sub">{{ row.upstreamEnterpriseName }}</small></template></el-table-column><el-table-column label="交接温度" width="120"><template #default="{ row }"><span :class="{ 'temp-ok': row.coldChainOk, 'temp-alert': row.coldChainOk === false }">{{ row.handoverTemp != null ? `${row.handoverTemp}°C` : '-' }}</span></template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }"><StatusTag :label="row.batchStatusName" :tone="statusTone(row.batchStatus)" /></template></el-table-column><el-table-column prop="createTime" label="创建时间" width="165" /><el-table-column label="操作" fixed="right" width="260"><template #default="{ row }"><el-button v-if="row.batchStatus === 1" link :icon="EditPen" @click="openEditor(row)">编辑</el-button><el-button v-if="row.batchStatus === 1" link type="primary" :icon="Promotion" @click="publish(row)">发布</el-button><el-button v-if="row.batchStatus === 4" link type="warning" :icon="Download" @click="offShelf(row)">下架</el-button><el-button v-if="row.batchStatus === 1" link type="danger" :icon="Delete" @click="remove(row)">删除</el-button><el-button v-if="row.batchStatus === 3 || row.batchStatus === 4" link :icon="Link" @click="showTrace(row)">溯源码</el-button></template></el-table-column><template #empty><EmptyState title="暂无批号" description="创建一个批号，开始记录产品流转" /></template></el-table><PaginationBar :total="total" :page="query.current || 1" :size="query.size || 10" @change="(page) => { query.current = page; load() }" @update:size="(size) => { query.size = size; query.current = 1; load() }" /></section><el-dialog v-model="dialogVisible" :title="editingId ? '编辑批号' : '新建批号'" width="680px" destroy-on-close><el-form :model="form" label-position="top"><div class="form-grid"><el-form-item label="产品批号" required><el-input v-model="form.batchNo" :disabled="Boolean(editingId)" placeholder="请输入唯一批号" /></el-form-item><el-form-item label="产品品种" required><el-input v-model="form.productVariety" placeholder="例如：阿根廷红虾" /></el-form-item><el-form-item label="来源类型"><el-select v-model="form.sourceType" style="width: 100%"><el-option label="养殖" :value="1" /><el-option label="捕捞" :value="2" /></el-select></el-form-item><el-form-item label="捕捞 / 养殖日期"><el-date-picker v-model="form.catchBreedDate" type="date" value-format="YYYY-MM-DD" style="width: 100%" /></el-form-item><el-form-item label="交接温度（°C）"><el-input-number v-model="form.departureTemp" :min="-40" :max="20" :precision="1" controls-position="right" style="width: 100%" /></el-form-item><el-form-item label="证书编号"><el-input v-model="form.certificateNo" /></el-form-item><el-form-item label="药残报告编号"><el-input v-model="form.drugReportNo" /></el-form-item><el-form-item label="捕捞日志编号"><el-input v-model="form.fishingLogNo" /></el-form-item><el-form-item class="form-grid__wide" label="备注"><el-input v-model="form.remark" type="textarea" :rows="3" maxlength="255" show-word-limit /></el-form-item><div class="form-grid__wide form-switches"><el-checkbox v-model="form.publish">保存后直接发布</el-checkbox><el-checkbox v-model="form.sendConfirmRequest">同时发送上游确认请求</el-checkbox></div></div></el-form><template #footer><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" :loading="actionLoading" @click="submit">保存批号</el-button></template></el-dialog></div></template>
